bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}' 2>/dev/null)" = true || exit 61
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'JS'
import pg from 'pg';import {readFileSync} from 'node:fs';
const e=process.env,pw=readFileSync('/run/secrets/videobot_db_password','utf8').trim();
const pool=new pg.Pool({host:e.VIDEOBOT_DB_HOST,user:e.VIDEOBOT_DB_USER,database:e.VIDEOBOT_DB_NAME,password:pw,max:1,connectionTimeoutMillis:5000});
try{
 const q=await pool.query("SELECT a.delivery_key AS old_key,b.delivery_key AS new_key FROM videobot_post_receipts a JOIN videobot_listings l ON l.listing_id=a.listing_id JOIN videobot_post_receipts b ON b.listing_id=a.listing_id AND b.revision=l.revision WHERE a.paid_message_id=4691 AND a.free_message_ids=ARRAY[4689,4690]::bigint[]");
 if(q.rowCount!==1)process.exitCode=70;
 else{
  const old=await pool.query("SELECT COUNT(*)::integer AS n FROM videobot_stars_ledger WHERE delivery_key=$1 AND kind='paid'",[q.rows[0].old_key]);
  const current=await pool.query("SELECT COUNT(*)::integer AS n FROM videobot_stars_ledger WHERE delivery_key=$1 AND kind='paid'",[q.rows[0].new_key]);
  const oldCount=old.rows[0].n,newCount=current.rows[0].n;
  if(oldCount>0&&newCount>0)process.exitCode=0;
  else if(oldCount>0&&newCount===0)process.exitCode=81;
  else if(oldCount===0&&newCount>0)process.exitCode=82;
  else process.exitCode=83;
 }
}catch(e){process.exitCode=79;}finally{await pool.end();}
JS
